css:
/* 次セクションを持ち上げてカードを飲む */
.cards{position:relative; z-index:2; margin-bottom:-130px}
.next-sec{background:#16181a; padding-top:150px}

/* ずらして覗かせる版（輪郭を一致させないのが肝） */
.hero{position:relative}
.hero::after{content:''; position:absolute; left:0; right:0; bottom:-22px;
  height:64px; z-index:-1;
  background:linear-gradient(90deg,#f7e6ef,#eef3f7);
  clip-path:polygon(8% 0,100% 0,96% 100%,0 100%)}
